mapper.update:
UPDATE workspace_memo
SET deleted_at = NOW(),
    updated_at = NOW()
WHERE id = #{id}
  AND workspace_id = #{workspaceId}
  AND deleted_at IS NULL

UPDATE workspace_memo
SET deleted_at = NULL,
    updated_at = NOW()
WHERE id = #{id}
  AND workspace_id = #{workspaceId}
  AND deleted_at IS NOT NULL

mapper.select:
SELECT *
FROM workspace_memo
WHERE id = #{id}
  AND workspace_id = #{workspaceId}
  AND deleted_at IS NULL

SELECT id, workspace_id, title, created_by, visibility, file_id, pinned, sort_order, created_at, updated_at
FROM workspace_memo
WHERE workspace_id = #{workspaceId}
  AND deleted_at IS NULL
  AND (
    lower(coalesce(visibility, 'shared')) <> 'private'
    OR created_by = #{userId}
  )
ORDER BY pinned DESC, sort_order ASC, updated_at DESC

SELECT id, workspace_id, title, created_by, visibility, file_id, pinned, sort_order, created_at, updated_at
FROM workspace_memo
WHERE file_id = #{fileId}
  AND workspace_id = #{workspaceId}
  AND deleted_at IS NULL
LIMIT 1
